input.new_string:
const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
const ITEM_BASE_PREMIUM = 100;

// Premiums round up, in the MHPCO's favour. The surcharge is added as a
// separate term rather than folded into a `base * 1.1` factor, which is not
// exact in binary floating point (100 * 1.1 === 110.00000000000001).
const quotePremium = (items: Item[]): number => {
  const base = items.length * ITEM_BASE_PREMIUM;
  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE);
};

const quote = (step: QuoteStep): QuoteResult => ({
  premium: quotePremium(step.items),
});

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => quote(step as QuoteStep)),
});

